// n8n Code node "Compter les sites" (mode: Run Once for All Items).
// Input: one item per page of results of the Notion query on the Sites database.
// Rule: a site counts on day J (today, Paris time) when it has a name, its contract
// has started (Date debut contrat <= J, or the page creation date when the start is
// empty), and it is not marked lost or archived with an end date already past.
const responses = $input.all().map(item => item.json);
if (responses.length === 0 || responses[responses.length - 1].has_more) {
  throw new Error('Lecture de la base Sites incomplète : relevé annulé pour ne pas écrire un faux total.');
}
const pages = responses.flatMap(r => r.results || []);
if (pages.length === 0) {
  throw new Error('Aucun site lu dans la base Sites : relevé annulé.');
}
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris' }).format(new Date());
const plain = prop => ((prop && (prop.title || prop.rich_text)) || []).map(t => t.plain_text || '').join('').trim();
const day = prop => ((prop && prop.date && prop.date.start) || '').slice(0, 10) || null;

let sites = 0, ext = 0, int = 0, portefeuille = 0;
for (const page of pages) {
  const p = page.properties || {};
  if (!plain(p['Nom'])) continue;
  const start = day(p['Date debut contrat']) || String(page.created_time || '').slice(0, 10);
  if (!start || start > today) continue;
  const lost = ((p['Reconduction'] && p['Reconduction'].multi_select) || []).some(o => o.name === 'Perdu')
    || (p['Archivé'] && p['Archivé'].checkbox === true);
  const end = day(p['Date fin Contrat']);
  if (lost && (!end || end < today)) continue;
  sites += 1;
  const side = (p['INT EXT ?'] && p['INT EXT ?'].select && p['INT EXT ?'].select.name) || '';
  if (side === 'EXT' || side === 'INT/EXT') ext += 1;
  if (side === 'INT' || side === 'INT/EXT') int += 1;
  portefeuille += (p['Total HT Annuel'] && p['Total HT Annuel'].number) || 0;
}
const mois = today.slice(0, 7);
portefeuille = Math.round(portefeuille * 100) / 100;
// Row of the "Sites gérés par mois" table, ready to send to Notion as-is.
const properties = {
  'Mois': { title: [{ text: { content: mois } }] },
  'Date': { date: { start: `${mois}-01` } },
  'Sites gérés': { number: sites },
  'Sites extérieur': { number: ext },
  'Sites intérieur': { number: int },
  'Portefeuille annuel HT': { number: portefeuille },
  'Source': { select: { name: 'Relevé' } },
  'Relevé le': { date: { start: today } },
};
return [{ json: { mois, releve: today, sites, ext, int, portefeuille, pagesLues: pages.length, properties } }];
